-- AEGIS users, sessions and runs (Oracle). Tables and columns follow
-- aegis_simplified_schema.sql; aegis_user_credentials is the one addition (that schema has no
-- password column). UUIDs are generated by the application and stored as VARCHAR2(36).
-- Create with:  python -m aegis_auth init-db   (AEGIS_AUTH_DB=oracle)

CREATE TABLE aegis_users (
    user_id       VARCHAR2(36) PRIMARY KEY,
    email         VARCHAR2(320) NOT NULL,
    display_name  VARCHAR2(255),
    user_role     VARCHAR2(40) NOT NULL,
    status        VARCHAR2(20) DEFAULT 'ACTIVE' NOT NULL,
    created_at    TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at    TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT uq_aegis_user_email UNIQUE (email),
    CONSTRAINT ck_aegis_user_status
        CHECK (status IN ('ACTIVE', 'DISABLED', 'LOCKED'))
);

CREATE TABLE aegis_user_sessions (
    session_id          VARCHAR2(36) PRIMARY KEY,
    user_id             VARCHAR2(36) NOT NULL,
    session_token_hash  VARCHAR2(255) NOT NULL,
    status              VARCHAR2(20) DEFAULT 'ACTIVE' NOT NULL,
    client_ip           VARCHAR2(64),
    user_agent          VARCHAR2(1000),
    created_at          TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    last_seen_at        TIMESTAMP WITH TIME ZONE,
    expires_at          TIMESTAMP WITH TIME ZONE NOT NULL,
    revoked_at          TIMESTAMP WITH TIME ZONE,
    CONSTRAINT fk_session_user
        FOREIGN KEY (user_id) REFERENCES aegis_users(user_id),
    CONSTRAINT uq_session_token_hash UNIQUE (session_token_hash),
    CONSTRAINT ck_session_status
        CHECK (status IN ('ACTIVE', 'EXPIRED', 'REVOKED'))
);

-- Addition: local password credentials (PBKDF2-SHA256 hash, never the password). Not needed
-- when sign-in moves to SSO (Microsoft Entra ID); see aegis_auth/README.md.
CREATE TABLE aegis_user_credentials (
    user_id               VARCHAR2(36) PRIMARY KEY,
    password_hash         VARCHAR2(255) NOT NULL,
    password_changed_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    must_change_password  NUMBER(1) DEFAULT 0 NOT NULL,
    failed_attempts       NUMBER DEFAULT 0 NOT NULL,
    locked_until          TIMESTAMP WITH TIME ZONE,
    last_login_at         TIMESTAMP WITH TIME ZONE,
    CONSTRAINT fk_credentials_user
        FOREIGN KEY (user_id) REFERENCES aegis_users(user_id)
);

CREATE TABLE aegis_runs (
    run_id                VARCHAR2(36) PRIMARY KEY,
    initiated_by_session_id VARCHAR2(36),
    source_file_name      VARCHAR2(255),
    status                VARCHAR2(40) NOT NULL,
    started_at            TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at            TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    completed_at          TIMESTAMP WITH TIME ZONE,
    CONSTRAINT fk_run_session
        FOREIGN KEY (initiated_by_session_id)
        REFERENCES aegis_user_sessions(session_id)
);

CREATE INDEX ix_sessions_user_status
    ON aegis_user_sessions (user_id, status);
